CREATE TABLE IF NOT EXISTS "users" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Login identity. 320 chars is the RFC 5321 maximum for an address.
	"email" VARCHAR(320) NOT NULL UNIQUE,
	-- Optional profile URL segment. Null until the user claims one, which is why it is not the key.
	"vanity_url" VARCHAR(50) UNIQUE,
	-- Real name as entered. Deliberately not unique - two people share a name all the time.
	"display_name" VARCHAR(120) NOT NULL,
	-- Date, not timestamp: a birthday is a calendar fact with no time zone.
	"birthdate" DATE,
	-- Free-text place on the profile.
	"hometown" VARCHAR(120),
	-- Denormalised count of accepted friendships. Read on every profile card, changed rarely.
	"friend_count" INTEGER NOT NULL DEFAULT 0,
	-- public | friends | friends_except | only_me | custom. Pre-fills the audience picker so a post never has to guess.
	"default_post_audience" VARCHAR(20) NOT NULL DEFAULT 'friends',
	-- Signup time.
	"created_at" TIMESTAMP NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "users" IS 'A person. The default audience lives on the user rather than in client settings because the server has to be able to reject a post whose audience was never chosen.';
COMMENT ON COLUMN "users"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "users"."email" IS 'Login identity. 320 chars is the RFC 5321 maximum for an address.';
COMMENT ON COLUMN "users"."vanity_url" IS 'Optional profile URL segment. Null until the user claims one, which is why it is not the key.';
COMMENT ON COLUMN "users"."display_name" IS 'Real name as entered. Deliberately not unique - two people share a name all the time.';
COMMENT ON COLUMN "users"."birthdate" IS 'Date, not timestamp: a birthday is a calendar fact with no time zone.';
COMMENT ON COLUMN "users"."hometown" IS 'Free-text place on the profile.';
COMMENT ON COLUMN "users"."friend_count" IS 'Denormalised count of accepted friendships. Read on every profile card, changed rarely.';
COMMENT ON COLUMN "users"."default_post_audience" IS 'public | friends | friends_except | only_me | custom. Pre-fills the audience picker so a post never has to guess.';
COMMENT ON COLUMN "users"."created_at" IS 'Signup time.';

CREATE TABLE IF NOT EXISTS "friendships" (
	-- The smaller of the two user ids. Storing the pair in sorted order is what makes one row represent both directions.
	"user_low_id" BIGINT,
	-- The larger of the two user ids. A CHECK that user_low_id < user_high_id keeps the canonical form enforced by the database, not by application discipline.
	"user_high_id" BIGINT,
	-- pending | accepted. A friendship only counts once both sides agree, so the request and the relationship are the same row in two states.
	"status" VARCHAR(12) NOT NULL DEFAULT 'pending',
	-- Which of the two sent the request. Needed because the sorted pair has thrown away the direction, and the UI must know who is waiting on whom.
	"requested_by_id" BIGINT NOT NULL,
	-- When the request was sent.
	"requested_at" TIMESTAMP NOT NULL DEFAULT now(),
	-- When it was accepted. Null while pending.
	"accepted_at" TIMESTAMP,
	PRIMARY KEY("user_low_id", "user_high_id")
);

COMMENT ON TABLE "friendships" IS 'Symmetric relationship in a single row. Friend lists are read with WHERE (user_low_id = :me OR user_high_id = :me) AND status = accepted, and the friend id is the column that is not :me. This is the key difference from a follow model, where two independent rows are the point.';
COMMENT ON COLUMN "friendships"."user_low_id" IS 'The smaller of the two user ids. Storing the pair in sorted order is what makes one row represent both directions.';
COMMENT ON COLUMN "friendships"."user_high_id" IS 'The larger of the two user ids. A CHECK that user_low_id < user_high_id keeps the canonical form enforced by the database, not by application discipline.';
COMMENT ON COLUMN "friendships"."status" IS 'pending | accepted. A friendship only counts once both sides agree, so the request and the relationship are the same row in two states.';
COMMENT ON COLUMN "friendships"."requested_by_id" IS 'Which of the two sent the request. Needed because the sorted pair has thrown away the direction, and the UI must know who is waiting on whom.';
COMMENT ON COLUMN "friendships"."requested_at" IS 'When the request was sent.';
COMMENT ON COLUMN "friendships"."accepted_at" IS 'When it was accepted. Null while pending.';

CREATE INDEX "idx_friendships_high_status"
ON "friendships" ("user_high_id", "status");
CREATE INDEX "idx_friendships_requested_by"
ON "friendships" ("requested_by_id", "status");

CREATE TABLE IF NOT EXISTS "friend_lists" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- User whose list this is. Lists are private to their owner and invisible to the people on them.
	"owner_id" BIGINT NOT NULL,
	-- List label, e.g. "Close Friends" or "Work".
	"name" VARCHAR(60) NOT NULL,
	-- Marks lists the platform creates and the user cannot delete, so product logic never has to hardcode names.
	"is_system" BOOLEAN NOT NULL DEFAULT false,
	-- Creation time.
	"created_at" TIMESTAMP NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "friend_lists" IS 'A named subset of the friends of one user. Its whole reason to exist is to be the target of a custom post audience.';
COMMENT ON COLUMN "friend_lists"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "friend_lists"."owner_id" IS 'User whose list this is. Lists are private to their owner and invisible to the people on them.';
COMMENT ON COLUMN "friend_lists"."name" IS 'List label, e.g. "Close Friends" or "Work".';
COMMENT ON COLUMN "friend_lists"."is_system" IS 'Marks lists the platform creates and the user cannot delete, so product logic never has to hardcode names.';
COMMENT ON COLUMN "friend_lists"."created_at" IS 'Creation time.';

CREATE UNIQUE INDEX "uq_friend_lists_owner_name"
ON "friend_lists" ("owner_id", "name");

CREATE TABLE IF NOT EXISTS "friend_list_members" (
	-- List being populated.
	"list_id" BIGINT,
	-- Friend placed on the list. Membership here does not imply friendship - the application checks both, so unfriending does not silently widen an audience.
	"member_id" BIGINT,
	-- When the friend was added to the list.
	"added_at" TIMESTAMP NOT NULL DEFAULT now(),
	PRIMARY KEY("list_id", "member_id")
);

COMMENT ON TABLE "friend_list_members" IS 'Join table between a list and the users on it. Kept separate from friendships so that curating a list never touches the relationship itself.';
COMMENT ON COLUMN "friend_list_members"."list_id" IS 'List being populated.';
COMMENT ON COLUMN "friend_list_members"."member_id" IS 'Friend placed on the list. Membership here does not imply friendship - the application checks both, so unfriending does not silently widen an audience.';
COMMENT ON COLUMN "friend_list_members"."added_at" IS 'When the friend was added to the list.';

CREATE TABLE IF NOT EXISTS "posts" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- User who wrote the post, even when it is published into a group or on a page.
	"author_id" BIGINT NOT NULL,
	-- Group the post was published to. Null for a profile or page post.
	"group_id" BIGINT,
	-- Page the post was published as. Null for a profile or group post. Exactly one of group_id and page_id may be set.
	"page_id" BIGINT,
	-- Post text. Null when the post is only an attachment or a share.
	"body" TEXT,
	-- Media and link previews as a small ordered document. Posts here have no separate media table because attachments are never addressed individually.
	"attachment" JSONB,
	-- public | friends | friends_except | only_me | custom. Evaluated on every read; a post is invisible until it passes this test.
	"audience" VARCHAR(20) NOT NULL DEFAULT 'friends',
	-- Friend list used when audience is custom or friends_except. Null otherwise - the column is only meaningful for those two values.
	"audience_list_id" BIGINT,
	-- Original post when this one is a share. Self-reference rather than a copy, so an edit or deletion of the original propagates.
	"shared_post_id" BIGINT,
	-- Denormalised total across all reaction types; the per-type breakdown comes from reactions when the user opens it.
	"reaction_count" INTEGER NOT NULL DEFAULT 0,
	-- Denormalised comment total.
	"comment_count" INTEGER NOT NULL DEFAULT 0,
	-- Publication time.
	"created_at" TIMESTAMP NOT NULL DEFAULT now(),
	-- Last edit. Its presence is what makes the client show the "edited" marker.
	"edited_at" TIMESTAMP,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "posts" IS 'Profile, group and page posts in one table, separated by which owner column is set. Audience scoping is stored with the post, not derived at read time, because the check has to be the same one that applied when it was written.';
COMMENT ON COLUMN "posts"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "posts"."author_id" IS 'User who wrote the post, even when it is published into a group or on a page.';
COMMENT ON COLUMN "posts"."group_id" IS 'Group the post was published to. Null for a profile or page post.';
COMMENT ON COLUMN "posts"."page_id" IS 'Page the post was published as. Null for a profile or group post. Exactly one of group_id and page_id may be set.';
COMMENT ON COLUMN "posts"."body" IS 'Post text. Null when the post is only an attachment or a share.';
COMMENT ON COLUMN "posts"."attachment" IS 'Media and link previews as a small ordered document. Posts here have no separate media table because attachments are never addressed individually.';
COMMENT ON COLUMN "posts"."audience" IS 'public | friends | friends_except | only_me | custom. Evaluated on every read; a post is invisible until it passes this test.';
COMMENT ON COLUMN "posts"."audience_list_id" IS 'Friend list used when audience is custom or friends_except. Null otherwise - the column is only meaningful for those two values.';
COMMENT ON COLUMN "posts"."shared_post_id" IS 'Original post when this one is a share. Self-reference rather than a copy, so an edit or deletion of the original propagates.';
COMMENT ON COLUMN "posts"."reaction_count" IS 'Denormalised total across all reaction types; the per-type breakdown comes from reactions when the user opens it.';
COMMENT ON COLUMN "posts"."comment_count" IS 'Denormalised comment total.';
COMMENT ON COLUMN "posts"."created_at" IS 'Publication time.';
COMMENT ON COLUMN "posts"."edited_at" IS 'Last edit. Its presence is what makes the client show the "edited" marker.';

CREATE INDEX "idx_posts_author_created"
ON "posts" ("author_id", "created_at");
CREATE INDEX "idx_posts_group_created"
ON "posts" ("group_id", "created_at");

CREATE TABLE IF NOT EXISTS "reactions" (
	-- Post being reacted to.
	"post_id" BIGINT,
	-- User reacting. The pair is the key, so a user holds exactly one reaction per post and changing it is an UPDATE, not a second row.
	"user_id" BIGINT,
	-- like | love | haha | wow | sad | angry | care. A column rather than a table per type, so adding a reaction is a deploy, not a migration.
	"reaction_type" VARCHAR(12) NOT NULL,
	-- First reaction time; preserved when the type is changed so ordering of the reactor list is stable.
	"created_at" TIMESTAMP NOT NULL DEFAULT now(),
	PRIMARY KEY("post_id", "user_id")
);

COMMENT ON TABLE "reactions" IS 'Typed reactions replacing a plain like. The per-type index is what makes the summary bar - the three most common faces and a total - a cheap grouped read.';
COMMENT ON COLUMN "reactions"."post_id" IS 'Post being reacted to.';
COMMENT ON COLUMN "reactions"."user_id" IS 'User reacting. The pair is the key, so a user holds exactly one reaction per post and changing it is an UPDATE, not a second row.';
COMMENT ON COLUMN "reactions"."reaction_type" IS 'like | love | haha | wow | sad | angry | care. A column rather than a table per type, so adding a reaction is a deploy, not a migration.';
COMMENT ON COLUMN "reactions"."created_at" IS 'First reaction time; preserved when the type is changed so ordering of the reactor list is stable.';

CREATE INDEX "idx_reactions_post_type"
ON "reactions" ("post_id", "reaction_type");

CREATE TABLE IF NOT EXISTS "comments" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Post being commented on, carried on replies too so a thread loads in one range scan.
	"post_id" BIGINT NOT NULL,
	-- User who wrote the comment.
	"author_id" BIGINT NOT NULL,
	-- Comment this replies to. Null for a top-level comment; replies are one level deep.
	"parent_comment_id" BIGINT,
	-- Comment text.
	"body" TEXT NOT NULL,
	-- Denormalised reaction total. Comment reactions are not stored per row in this model.
	"reaction_count" INTEGER NOT NULL DEFAULT 0,
	-- Posting time and the sort key within a thread.
	"created_at" TIMESTAMP NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "comments" IS 'Two-level comment threads. A comment inherits the audience of its post: there is no separate visibility here, which is exactly why audience lives on the post.';
COMMENT ON COLUMN "comments"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "comments"."post_id" IS 'Post being commented on, carried on replies too so a thread loads in one range scan.';
COMMENT ON COLUMN "comments"."author_id" IS 'User who wrote the comment.';
COMMENT ON COLUMN "comments"."parent_comment_id" IS 'Comment this replies to. Null for a top-level comment; replies are one level deep.';
COMMENT ON COLUMN "comments"."body" IS 'Comment text.';
COMMENT ON COLUMN "comments"."reaction_count" IS 'Denormalised reaction total. Comment reactions are not stored per row in this model.';
COMMENT ON COLUMN "comments"."created_at" IS 'Posting time and the sort key within a thread.';

CREATE INDEX "idx_comments_post_created"
ON "comments" ("post_id", "created_at");

CREATE TABLE IF NOT EXISTS "groups" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Group name shown in search and headers.
	"name" VARCHAR(160) NOT NULL,
	-- URL segment.
	"slug" VARCHAR(180) NOT NULL UNIQUE,
	-- Long-form about text.
	"description" TEXT,
	-- public | private | hidden. Public groups are readable by anyone, private ones need membership, hidden ones are unsearchable as well.
	"privacy" VARCHAR(12) NOT NULL DEFAULT 'public',
	-- When true a join creates a pending membership instead of an active one.
	"requires_approval" BOOLEAN NOT NULL DEFAULT false,
	-- Denormalised active-member count for the directory listing.
	"member_count" INTEGER NOT NULL DEFAULT 0,
	-- Founder. Null once that account is deleted; the group outlives its creator.
	"created_by_id" BIGINT,
	-- Creation time.
	"created_at" TIMESTAMP NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "groups" IS 'A community with its own membership and its own posts. Groups are not derived from friendship - that independence is the reason they need a membership table of their own.';
COMMENT ON COLUMN "groups"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "groups"."name" IS 'Group name shown in search and headers.';
COMMENT ON COLUMN "groups"."slug" IS 'URL segment.';
COMMENT ON COLUMN "groups"."description" IS 'Long-form about text.';
COMMENT ON COLUMN "groups"."privacy" IS 'public | private | hidden. Public groups are readable by anyone, private ones need membership, hidden ones are unsearchable as well.';
COMMENT ON COLUMN "groups"."requires_approval" IS 'When true a join creates a pending membership instead of an active one.';
COMMENT ON COLUMN "groups"."member_count" IS 'Denormalised active-member count for the directory listing.';
COMMENT ON COLUMN "groups"."created_by_id" IS 'Founder. Null once that account is deleted; the group outlives its creator.';
COMMENT ON COLUMN "groups"."created_at" IS 'Creation time.';

CREATE TABLE IF NOT EXISTS "group_members" (
	-- Group joined.
	"group_id" BIGINT,
	-- Member.
	"user_id" BIGINT,
	-- member | moderator | admin. Authorisation for pinning, removing and approving is read from here, never from the post.
	"role" VARCHAR(12) NOT NULL DEFAULT 'member',
	-- active | pending | banned. A ban is kept as a row so the same person cannot rejoin by leaving.
	"status" VARCHAR(12) NOT NULL DEFAULT 'active',
	-- When the membership was created, including while still pending.
	"joined_at" TIMESTAMP NOT NULL DEFAULT now(),
	PRIMARY KEY("group_id", "user_id")
);

COMMENT ON TABLE "group_members" IS 'Membership with a role and a lifecycle state. Keeping bans here rather than deleting the row is what makes re-joining enforceable.';
COMMENT ON COLUMN "group_members"."group_id" IS 'Group joined.';
COMMENT ON COLUMN "group_members"."user_id" IS 'Member.';
COMMENT ON COLUMN "group_members"."role" IS 'member | moderator | admin. Authorisation for pinning, removing and approving is read from here, never from the post.';
COMMENT ON COLUMN "group_members"."status" IS 'active | pending | banned. A ban is kept as a row so the same person cannot rejoin by leaving.';
COMMENT ON COLUMN "group_members"."joined_at" IS 'When the membership was created, including while still pending.';

CREATE INDEX "idx_group_members_user_status"
ON "group_members" ("user_id", "status");
CREATE INDEX "idx_group_members_group_role"
ON "group_members" ("group_id", "role");

CREATE TABLE IF NOT EXISTS "pages" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Page name.
	"name" VARCHAR(160) NOT NULL,
	-- URL segment.
	"slug" VARCHAR(180) NOT NULL UNIQUE,
	-- Directory category, e.g. restaurant or musician.
	"category" VARCHAR(60) NOT NULL,
	-- Confirmed as the official presence of the entity.
	"is_verified" BOOLEAN NOT NULL DEFAULT false,
	-- Denormalised follower total shown on the header.
	"follower_count" INTEGER NOT NULL DEFAULT 0,
	-- Account that administers the page. Null if that account is removed, leaving the page orphaned rather than deleted.
	"owner_user_id" BIGINT,
	-- Creation time.
	"created_at" TIMESTAMP NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "pages" IS 'A public presence for a business or public figure. Unlike a profile it is followed, not friended - which is why pages need their own asymmetric edge table.';
COMMENT ON COLUMN "pages"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "pages"."name" IS 'Page name.';
COMMENT ON COLUMN "pages"."slug" IS 'URL segment.';
COMMENT ON COLUMN "pages"."category" IS 'Directory category, e.g. restaurant or musician.';
COMMENT ON COLUMN "pages"."is_verified" IS 'Confirmed as the official presence of the entity.';
COMMENT ON COLUMN "pages"."follower_count" IS 'Denormalised follower total shown on the header.';
COMMENT ON COLUMN "pages"."owner_user_id" IS 'Account that administers the page. Null if that account is removed, leaving the page orphaned rather than deleted.';
COMMENT ON COLUMN "pages"."created_at" IS 'Creation time.';

CREATE TABLE IF NOT EXISTS "page_follows" (
	-- Page followed.
	"page_id" BIGINT,
	-- Follower.
	"user_id" BIGINT,
	-- all | standard | off. Per-page delivery preference, which is the main thing a follow carries beyond existence.
	"notification_level" VARCHAR(12) NOT NULL DEFAULT 'standard',
	-- When the follow started.
	"followed_at" TIMESTAMP NOT NULL DEFAULT now(),
	PRIMARY KEY("page_id", "user_id")
);

COMMENT ON TABLE "page_follows" IS 'The asymmetric counterpart to friendships: nobody has to approve, and the page never follows back. Two edge tables with different rules is more honest than one with a type column.';
COMMENT ON COLUMN "page_follows"."page_id" IS 'Page followed.';
COMMENT ON COLUMN "page_follows"."user_id" IS 'Follower.';
COMMENT ON COLUMN "page_follows"."notification_level" IS 'all | standard | off. Per-page delivery preference, which is the main thing a follow carries beyond existence.';
COMMENT ON COLUMN "page_follows"."followed_at" IS 'When the follow started.';

CREATE TABLE IF NOT EXISTS "events" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Event name.
	"title" VARCHAR(200) NOT NULL,
	-- Details shown on the event page.
	"description" TEXT,
	-- User hosting. Null when a page or group hosts instead.
	"host_user_id" BIGINT,
	-- Page hosting. Null when a user hosts.
	"host_page_id" BIGINT,
	-- Group the event belongs to, when created inside one. Drives who can see it.
	"group_id" BIGINT,
	-- Start instant in UTC.
	"starts_at" TIMESTAMP NOT NULL,
	-- End instant. Null for open-ended events.
	"ends_at" TIMESTAMP,
	-- IANA zone of the venue. Stored alongside the UTC instant so the page can show local time even after a DST rule change.
	"timezone" VARCHAR(64) NOT NULL DEFAULT 'UTC',
	-- Place name. Null for an online event.
	"venue_name" VARCHAR(200),
	-- Switches the page from a map to a join link.
	"is_online" BOOLEAN NOT NULL DEFAULT false,
	-- public | friends | invite_only. Independent of the host, so a public page can still run a closed event.
	"privacy" VARCHAR(12) NOT NULL DEFAULT 'public',
	-- Creation time.
	"created_at" TIMESTAMP NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "events" IS 'An event with a host that may be a person, a page or a group. Storing the UTC instant and the IANA zone separately is what keeps a rescheduled or re-zoned event correct.';
COMMENT ON COLUMN "events"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "events"."title" IS 'Event name.';
COMMENT ON COLUMN "events"."description" IS 'Details shown on the event page.';
COMMENT ON COLUMN "events"."host_user_id" IS 'User hosting. Null when a page or group hosts instead.';
COMMENT ON COLUMN "events"."host_page_id" IS 'Page hosting. Null when a user hosts.';
COMMENT ON COLUMN "events"."group_id" IS 'Group the event belongs to, when created inside one. Drives who can see it.';
COMMENT ON COLUMN "events"."starts_at" IS 'Start instant in UTC.';
COMMENT ON COLUMN "events"."ends_at" IS 'End instant. Null for open-ended events.';
COMMENT ON COLUMN "events"."timezone" IS 'IANA zone of the venue. Stored alongside the UTC instant so the page can show local time even after a DST rule change.';
COMMENT ON COLUMN "events"."venue_name" IS 'Place name. Null for an online event.';
COMMENT ON COLUMN "events"."is_online" IS 'Switches the page from a map to a join link.';
COMMENT ON COLUMN "events"."privacy" IS 'public | friends | invite_only. Independent of the host, so a public page can still run a closed event.';
COMMENT ON COLUMN "events"."created_at" IS 'Creation time.';

CREATE INDEX "idx_events_starts_at"
ON "events" ("starts_at");

CREATE TABLE IF NOT EXISTS "event_rsvps" (
	-- Event responded to.
	"event_id" BIGINT,
	-- Responder.
	"user_id" BIGINT,
	-- going | interested | declined. Three states rather than a boolean, because "interested" is the one the reminder system acts on.
	"response" VARCHAR(12) NOT NULL,
	-- Additional unnamed guests. Capacity planning needs the number even when the people are not accounts.
	"guest_count" SMALLINT NOT NULL DEFAULT 0,
	-- When the response was last changed; an RSVP is overwritten, not appended.
	"responded_at" TIMESTAMP NOT NULL DEFAULT now(),
	PRIMARY KEY("event_id", "user_id")
);

COMMENT ON TABLE "event_rsvps" IS 'One row per invitee, updated in place. The response index turns the three guest-list tabs into three index scans.';
COMMENT ON COLUMN "event_rsvps"."event_id" IS 'Event responded to.';
COMMENT ON COLUMN "event_rsvps"."user_id" IS 'Responder.';
COMMENT ON COLUMN "event_rsvps"."response" IS 'going | interested | declined. Three states rather than a boolean, because "interested" is the one the reminder system acts on.';
COMMENT ON COLUMN "event_rsvps"."guest_count" IS 'Additional unnamed guests. Capacity planning needs the number even when the people are not accounts.';
COMMENT ON COLUMN "event_rsvps"."responded_at" IS 'When the response was last changed; an RSVP is overwritten, not appended.';

CREATE INDEX "idx_event_rsvps_event_response"
ON "event_rsvps" ("event_id", "response");

